import Testing
@testable import Screens

struct MemberViewTests {
    @Test("member-view is refused to someone signed in without members.read")
    func refused() {
        #expect(Access.decide(permission: memberViewSchema.permission, session: Session(signedIn: true, permissions: [])) == .refused)
    }

    @Test("member-view sends someone signed out to sign in")
    func signIn() {
        #expect(Access.decide(permission: memberViewSchema.permission, session: Session(signedIn: false, permissions: [])) == .signIn)
    }

    @Test("member-view opens to someone who holds members.read")
    func allowed() {
        #expect(Access.decide(permission: memberViewSchema.permission, session: Session(signedIn: true, permissions: ["members.read"])) == .allowed)
    }
}
